VALUES ('90255e81-bda8-5e80-952b-40fb536cc3a4', 'e5a6f479-7aeb-5ee5-9953-79462c010d05', 'cfba9bcd-226f-5d19-b19c-3dff0843a16b', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Parent Organization', 'Immediate parent organizational unit. Supports enterprise hierarchy and organizational scope. Zero or one immediate parent. Determines inherited organizational context where explicitly supported.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
