VALUES ('dbba51a3-2e7e-5544-83d2-9f84ac1270b5', '11cfac2c-f6e3-5bc1-b56f-3459ff2f54a1', '9eb1d5e3-6447-55e8-a905-05249103188d', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Status', 'Controls whether the currency is available for new monetary transactions. Used by pricing, order, invoicing, payment, banking, and accounting validation. Retiring a currency must not invalidate historical transactions expressed in that currency. New transactions should use ACTIVE currencies unless an authorized legacy exception applies. Available for normal financial activity. Temporarily unavailable for new normal activity. No longer available for new normal activity while historical financial records remain valid. Required for transaction eligibility. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
