VALUES ('f02526ca-114a-58a1-a75e-61066a266b73', '992f998c-646c-50bc-b49e-1507fde8693b', '51479f3b-1e1d-58dc-a6fa-56560cb80aa8', 'Calendar', 'Shows one Calendar at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
