VALUES ('7c677c7b-24d0-5b53-b57d-4b3b2a477565', '3a5b7392-db09-57c4-bb31-b7e9274ceeb6', 'status', 'Status', 'Operational execution state of the shipment. Controls booking, dispatch, tracking, delivery, exception and cancellation actions. Status is not inventory status and does not itself prove customer acceptance or invoice payment. Drives permitted logistics transitions and downstream fulfillment/movement workflows.', 1027, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
