-- --------------------------------------------------------------------------
-- Vehicle (bus_vehicle)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f98b9ce4-df1e-5c3c-8f0a-feb2ffe636f8', 'Vehicle', 'Maintain Vehicle records', 'Create, find and maintain Vehicle records. The list shows every Vehicle you have access to — select a row to open it, or use New to add one. Each row is a single Vehicle, described by 7 fields.

Id and Registration Number are unique: no two Vehicle records may share the same value, and a save that would duplicate one is rejected. Registration Number, Vehicle Type and Status must be filled in before the record can be saved.

Every Vehicle points at Location. Choose the linked record from the lookup on those fields rather than typing an identifier. Trip Segment refers back to Vehicle, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Vehicle then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Vehicle with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0777a7de-46ff-5aa0-87bf-8a6341357c18', 'bus_vehicle', 'Vehicle', 'Represents a logistics asset called Vehicle within the CEDM business model. Vehicle is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate Vehicle records. The entity participates in a wider business graph through relationships with Party, Location, ContainerMovement. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical Vehicle record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, 'f98b9ce4-df1e-5c3c-8f0a-feb2ffe636f8', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('07c1e4ca-faf1-5605-9279-ba72ed03803d', 'f98b9ce4-df1e-5c3c-8f0a-feb2ffe636f8', '0777a7de-46ff-5aa0-87bf-8a6341357c18', 'Vehicle', 'Shows one Vehicle at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Location is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ababe5c1-9e27-5cda-87fc-e592c30e32d5', '0777a7de-46ff-5aa0-87bf-8a6341357c18', 'id', 'Id', 'Identifies the vehicle record associated with this Vehicle. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating Vehicle records, where applicable. Its meaning is specific to Vehicle; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8ee3797c-6a3f-581d-8c86-05b44884f89d', '0777a7de-46ff-5aa0-87bf-8a6341357c18', 'registration_number', 'Registration Number', 'Captures the business meaning of registration number for the Vehicle. It is interpreted together with the entity''s other attributes and relationships to support the processes that manage this record. Used when creating, reviewing, searching, validating, reporting on, or integrating Vehicle records, where applicable. Its meaning is specific to Vehicle; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('412fb480-1554-55d5-aa36-5aed7061bb18', '0777a7de-46ff-5aa0-87bf-8a6341357c18', 'vehicle_type', 'Vehicle Type', 'Captures the business meaning of vehicle type for the Vehicle. It is interpreted together with the entity''s other attributes and relationships to support the processes that manage this record. Used when creating, reviewing, searching, validating, reporting on, or integrating Vehicle records, where applicable. Its meaning is specific to Vehicle; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Represents the truck state or classification in the context of Vehicle. Represents the tractor state or classification in the context of Vehicle. Represents the trailer state or classification in the context of Vehicle. Represents the forklift state or classification in the context of Vehicle. Represents the crane state or classification in the context of Vehicle. Represents the other state or classification in the context of Vehicle. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 1034, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3d360b93-2e5d-55a5-b5b0-da577925c0f1', '0777a7de-46ff-5aa0-87bf-8a6341357c18', 'capacity', 'Capacity', 'Captures the business meaning of capacity for the Vehicle. It is interpreted together with the entity''s other attributes and relationships to support the processes that manage this record. Used when creating, reviewing, searching, validating, reporting on, or integrating Vehicle records, where applicable. Its meaning is specific to Vehicle; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Optional because the business concept can remain valid when this value is not yet known or is not applicable.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b85705b7-c926-52ed-ab7c-c03870783d2b', '0777a7de-46ff-5aa0-87bf-8a6341357c18', 'status', 'Status', 'The lifecycle state of the record. It controls which business actions are normally permitted and how the record is treated by related processes. Used when creating, reviewing, searching, validating, reporting on, or integrating Vehicle records, where applicable. Its meaning is specific to Vehicle; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Represents the active state or classification in the context of Vehicle. Represents the maintenance state or classification in the context of Vehicle. Represents the out of service state or classification in the context of Vehicle. Represents the retired state or classification in the context of Vehicle. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 1033, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ec0df0b8-66db-5ee5-aa3b-d21a0a039487', '0777a7de-46ff-5aa0-87bf-8a6341357c18', 'operator_id', 'Operator', 'Connects Vehicle to Party so related business context can be navigated and enforced. Used when processes need to find or reason about Party records associated with a Vehicle. The declared cardinality 0..1 expresses how many related records may participate in the relationship. The relationship is part of the CEDM semantic graph and is interpreted together with source and target entities, ownership, conditions, and invariants.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e94b2c08-fe1c-5878-bbea-3e39408de9f6', '0777a7de-46ff-5aa0-87bf-8a6341357c18', 'location_id', 'Location', 'Connects Vehicle to Location so related business context can be navigated and enforced. Used when processes need to find or reason about Location records associated with a Vehicle. The declared cardinality 0..1 expresses how many related records may participate in the relationship. The relationship is part of the CEDM semantic graph and is interpreted together with source and target entities, ownership, conditions, and invariants.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
