VALUES ('8cf8e643-adc7-5b75-97ef-0f95db346ea1', '5990f296-d406-5b61-b218-856ca3029bcb', 'unit_of_measure_id', 'Unit Of Measure', 'The UnitOfMeasure this InventoryMovement belongs to.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
