INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('64e4fcad-231f-5fb2-9d84-bc6f187bcb03', '5990f296-d406-5b61-b218-856ca3029bcb', 'shipment_line_id', 'Shipment Line', 'Shipment line associated with this inventory event when logistics execution applies. Preserves line-level transport-to-stock provenance. Dispatch, transfer, receipt reconciliation, claims, and audit. Optional for inventory events unrelated to shipment execution. Product, quantity, UOM and direction must reconcile with shipment execution and source transaction.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
