VALUES ('35a3a434-0e0a-5b94-a0f0-9ded5c7ef82d', '5990f296-d406-5b61-b218-856ca3029bcb', 'product_id', 'Product', 'Product whose inventory state is affected. Connects event to product master, units and policies. Exactly one product is affected. Identifies stock item.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
