-- Carrier (bus_carrier)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c8526590-b65c-5f19-9525-23db73fcfc2e', 'Carrier', 'Maintain Carrier records', 'Create, find and maintain Carrier records. The list shows every Carrier you have access to — select a row to open it, or use New to add one. Each row is a single Carrier, described by 3 fields.

Id is unique: no two Carrier records may share the same value, and a save that would duplicate one is rejected. Party must be filled in before the record can be saved.

Every Carrier points at Party. Choose the linked record from the lookup on those fields rather than typing an identifier. Shipment refers back to Carrier, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Carrier then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Carrier with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('407b94b6-86ed-58e7-9256-bf5f261167d1', 'bus_carrier', 'Carrier', 'A governed logistics service provider responsible for transporting shipments, consignments, or loads. Provide canonical implementation-neutral semantics for Carrier across enterprise applications. A governed logistics service provider responsible for transporting shipments, consignments, or loads. Used in CRM, sales, fulfillment, logistics, reporting, integration, or audit processes where this concept applies. Connects to canonical parties, commercial transactions, logistics execution, and downstream evidence without replacing their authoritative records. Created and progressed through governed business workflow; completed history is retained and corrections are explicit. Commercial management, fulfillment, logistics execution, reconciliation, reporting, and audit. Enterprise sales and supply-chain operations.', 'A', FALSE, FALSE, FALSE, TRUE, 'c8526590-b65c-5f19-9525-23db73fcfc2e', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b8ff063e-aa63-5768-a857-e3e06ac528fe', 'c8526590-b65c-5f19-9525-23db73fcfc2e', '407b94b6-86ed-58e7-9256-bf5f261167d1', 'Carrier', 'Shows one Carrier at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Party is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
