VALUES ('a6cc8f22-fcb1-560c-81de-f79b444b4494', 'c4b29932-a503-56c2-bbbe-33d9119d6656', 'e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'Delivery', 'Shows one Delivery at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Shipment is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
