INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0eb7eb68-fe5f-5493-8d11-74fb9134d1b3', 'Fulfillment', 'Maintain Fulfillment records', 'Create, find and maintain Fulfillment records. The list shows every Fulfillment you have access to — select a row to open it, or use New to add one. Each row is a single Fulfillment, described by 2 fields.

Id is unique: no two Fulfillment records may share the same value, and a save that would duplicate one is rejected.

Every save starts as a Draft. The business rules and workflows attached to Fulfillment then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Fulfillment with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
