INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9ecc5271-d005-5eaa-a5b2-1378c86eba2b', 'Tracking Event', 'Maintain Tracking Event records', 'Create, find and maintain Tracking Event records. The list shows every Tracking Event you have access to — select a row to open it, or use New to add one. Each row is a single Tracking Event, described by 3 fields.

Id is unique: no two Tracking Event records may share the same value, and a save that would duplicate one is rejected. Shipment must be filled in before the record can be saved.

Every Tracking Event points at Shipment. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Tracking Event then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Tracking Event with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
