INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('83e41005-f7cb-5571-89ee-73739f398fa1', 'Trip', 'Maintain Trip records', 'Create, find and maintain Trip records. The list shows every Trip you have access to — select a row to open it, or use New to add one. Each row is a single Trip, described by 6 fields.

Id and Trip Number are unique: no two Trip records may share the same value, and a save that would duplicate one is rejected. Trip Number, Start Date and Status must be filled in before the record can be saved.

Party and Trip Segment refer back to Trip, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Trip then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Trip with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a8db435a-a884-556a-b609-6ec675ae8750', 'bus_trip', 'Trip', 'Represents a travel entity called Trip within the CEDM business model. Trip is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate Trip records. The entity participates in a wider business graph through relationships with Party, TripSegment, BusinessTransaction. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical Trip record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, '83e41005-f7cb-5571-89ee-73739f398fa1', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9680abbf-cb98-5f19-8939-ab85fde46af6', '83e41005-f7cb-5571-89ee-73739f398fa1', 'a8db435a-a884-556a-b609-6ec675ae8750', 'Trip', 'Shows one Trip at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
