VALUES ('be1f581f-5833-5f00-82ca-186609ea6479', 'a8db435a-a884-556a-b609-6ec675ae8750', 'id', 'Id', 'Identifies the trip record associated with this Trip. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating Trip records, where applicable. Its meaning is specific to Trip; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
