INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('20214290-0c39-5a5f-bd36-30ba1754ec72', 'a8db435a-a884-556a-b609-6ec675ae8750', 'status', 'Status', 'The lifecycle state of the record. It controls which business actions are normally permitted and how the record is treated by related processes. Used when creating, reviewing, searching, validating, reporting on, or integrating Trip records, where applicable. Its meaning is specific to Trip; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Represents the planned state or classification in the context of Trip. Represents the booked state or classification in the context of Trip. Represents the in progress state or classification in the context of Trip. Represents the completed state or classification in the context of Trip. Represents the cancelled state or classification in the context of Trip. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 1030, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1be50b7a-2dad-5682-aa0b-dfc1d77c4ae2', '9680abbf-cb98-5f19-8939-ab85fde46af6', 'be1f581f-5833-5f00-82ca-186609ea6479', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Id', 'Identifies the trip record associated with this Trip. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating Trip records, where applicable. Its meaning is specific to Trip; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value. Must be unique: a save is rejected if another Trip already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
