VALUES ('848aae0a-db31-5286-a94b-bd52553edfbc', '31e7585d-7d98-517e-a852-23cd4db72450', '283ae8f2-cc52-5cc3-8d60-245818ac2fa9', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Id', 'Stable identifier for the Customer business relationship. Used by orders invoices receivables service pricing credit contracts and analytics. Party identifies the underlying party while customerId identifies the customer relationship. Provides the stable customer reference carried into SalesOrder Invoice Payment shipment service and receivables workflows. Required for unambiguous customer transaction traceability. Must be unique: a save is rejected if another Customer already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
