INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c98f2388-fe45-5a49-80c2-6d4dadeed031', '31e7585d-7d98-517e-a852-23cd4db72450', '3fd9a157-5304-5724-a1a6-15a494d74d58', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Party Role', 'Links Customer to its underlying PartyRole. Resolves common party identity and role information. Customer is a role specialization and must not duplicate Party identity. Supplies common party context to customer-facing workflows. Required because Customer depends on PartyRole. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Customer already uses this value.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
