INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('795be65e-3ff5-5f8b-93b1-25bc8f657f80', 'Integration Endpoint', 'Maintain Integration Endpoint records', 'Create, find and maintain Integration Endpoint records. The list shows every Integration Endpoint you have access to — select a row to open it, or use New to add one. Each row is a single Integration Endpoint, described by 2 fields.

Id is unique: no two Integration Endpoint records may share the same value, and a save that would duplicate one is rejected.

Every save starts as a Draft. The business rules and workflows attached to Integration Endpoint then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Integration Endpoint with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('02f26e41-cf88-5ee1-bc35-229b128172e3', 'bus_integration_endpoint', 'Integration Endpoint', 'A governed logical endpoint through which enterprise messages or business events are exchanged with an internal or external system. Provide canonical implementation-neutral integration semantics for IntegrationEndpoint. A governed logical endpoint through which enterprise messages or business events are exchanged with an internal or external system. Used for event publication, message exchange, delivery, retry, reconciliation, integration operations, and audit. Carries or routes evidence derived from authoritative domain transactions without replacing those source records. Created and processed through governed integration states; attempts and finalized evidence are retained. Event publication, messaging, endpoint delivery, retry, dead-letter handling, reconciliation, and audit. Enterprise application integration and event-driven workflows.', 'A', FALSE, FALSE, FALSE, TRUE, '795be65e-3ff5-5f8b-93b1-25bc8f657f80', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
