INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'bus_shipment_line', 'Shipment Line', 'Line-level logistics execution connecting commercial demand to physical transport and inventory evidence. ShipmentLine says what quantity moved in logistics; InventoryMovement says what happened to stock. Outbound fulfillment, inbound transport, transfers, returns, carrier operations, claims, and audit. Shipment supplies logistics context; order lines supply demand/commitment; InventoryMovement supplies stock effects. Planned → dispatched → delivered or exception/cancellation according to parent shipment. Quantity or source-line changes revalidate allocation, inventory, receiving, fulfillment, and delivery workflows.', 'A', FALSE, FALSE, FALSE, TRUE, 'ab040334-78c5-5316-9ee9-7b16736a368b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0e7c10e7-c46d-5b78-86bb-788f58347efa', 'ab040334-78c5-5316-9ee9-7b16736a368b', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'Shipment Line', 'Shows one Shipment Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Shipment, Product, Unit Of Measure and Sales Order Line are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
