VALUES ('5249e5fb-accc-553a-b37a-5b0727fee23b', '78ef3ff5-3eb9-52ab-9d83-dcce53b45b9f', '1f7ddc88-5364-5b0b-84b7-c000156f4d91', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Origin', 'Connects TripSegment to Location so related business context can be navigated and enforced. Used when processes need to find or reason about Location records associated with a TripSegment. The declared cardinality 1 expresses how many related records may participate in the relationship. The relationship is part of the CEDM semantic graph and is interpreted together with source and target entities, ownership, conditions, and invariants. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
